from __future__ import annotations

import argparse
import json
from pathlib import Path


HTML_TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Stonkfly / NSE Neural Trace</title>
<style>
:root{--bg:#071014;--panel:#0d1d22;--panel2:#12272c;--line:#244047;--ink:#edf5f1;--muted:#91a8ac;--mint:#a7eb7a;--amber:#f3d476;--red:#ff746f;--cyan:#71e0d2;--purple:#b9a2ff;--shadow:0 18px 45px rgba(0,0,0,.24)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% -10%,#173a39 0,transparent 38%),var(--bg);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,system-ui,sans-serif}button,input{font:inherit}button{color:inherit}.app{max-width:1500px;margin:auto;padding:22px clamp(16px,3vw,42px) 40px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}.eyebrow{color:var(--mint);font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.title{font-size:clamp(27px,4vw,46px);font-weight:800;letter-spacing:-.055em;margin:5px 0}.sub{color:var(--muted);margin:0}.status{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 11px;color:var(--muted);background:rgba(18,39,44,.7);font-size:12px}.pill.live{color:var(--mint);border-color:#476e4b}.grid{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(340px,.85fr);gap:16px}.panel{background:linear-gradient(145deg,rgba(18,39,44,.96),rgba(10,27,32,.96));border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow);overflow:hidden}.panel-head{padding:18px 20px 12px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid rgba(36,64,71,.65)}.panel-title{font-size:15px;font-weight:750}.panel-meta{font-size:12px;color:var(--muted)}.stage{min-height:510px;position:relative;background:radial-gradient(circle at 50% 45%,rgba(80,155,120,.14),transparent 37%),linear-gradient(160deg,#10262a,#081518)}.stage:before{content:"";position:absolute;inset:25px;background-image:linear-gradient(rgba(167,235,122,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(167,235,122,.045) 1px,transparent 1px);background-size:36px 36px;mask-image:linear-gradient(to bottom,transparent,#000 20%,#000 80%,transparent)}#fly-svg{width:100%;height:400px;display:block;position:relative;z-index:1}.fly-label{position:absolute;left:20px;bottom:16px;color:var(--muted);font-size:12px;max-width:360px}.fly-state{position:absolute;right:20px;top:18px;font-size:20px;font-weight:850;letter-spacing:.04em;padding:10px 14px;border-radius:13px;border:1px solid var(--line);background:rgba(7,16,20,.7);z-index:2}.fly-state.BUY{color:var(--mint);border-color:#557c4d}.fly-state.SELL{color:var(--red);border-color:#874b4b}.fly-state.HOLD{color:var(--muted)}.brain{padding-bottom:16px}.brain-map{height:265px;position:relative}.brain-map svg{width:100%;height:100%}.wire{stroke:#4b7477;stroke-width:1.5;opacity:.82}.node{stroke:#071014;stroke-width:2}.node.input{fill:var(--cyan)}.node.kc{fill:var(--purple)}.node.decision{fill:var(--mint)}.node.gate{fill:var(--amber)}.node.dan{fill:var(--red)}.brain-caption{padding:0 20px;color:var(--muted);font-size:11px}.readouts{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;padding:14px 20px 0}.readout{padding:11px 12px;border:1px solid rgba(36,64,71,.8);border-radius:13px;background:rgba(7,16,20,.35)}.readout .k{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.readout .v{font-size:19px;font-weight:800;margin-top:2px;font-variant-numeric:tabular-nums}.v.mint{color:var(--mint)}.v.amber{color:var(--amber)}.v.red{color:var(--red)}.timeline{margin-top:16px}.timeline-body{padding:16px 20px 20px}.chart{height:190px;width:100%;display:block;border-radius:14px;background:#09171b;border:1px solid rgba(36,64,71,.8)}.range{width:100%;accent-color:var(--mint);margin:14px 0 4px}.event-line{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:12px}.event-line strong{color:var(--ink)}.legend{display:flex;gap:13px;flex-wrap:wrap;margin-top:11px;color:var(--muted);font-size:11px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.controls{display:flex;gap:8px;align-items:center}.controls button{border:1px solid var(--line);background:#142c31;border-radius:9px;padding:7px 10px;cursor:pointer}.controls button:hover{border-color:#63857e}.note{margin-top:16px;padding:12px 14px;border-left:3px solid var(--amber);background:rgba(243,212,118,.08);color:var(--muted);font-size:12px;border-radius:9px}.pulse{animation:pulse 900ms ease-out}@keyframes pulse{0%{filter:drop-shadow(0 0 0 transparent)}40%{filter:drop-shadow(0 0 18px var(--pulse-color))}100%{filter:drop-shadow(0 0 0 transparent)}}.leg{stroke:#9bb8b0;stroke-width:4;stroke-linecap:round;fill:none;transition:transform .35s ease}.wing{fill:rgba(113,224,210,.12);stroke:#71b8b0;stroke-width:2;transition:transform .45s ease,opacity .45s ease}.bodypart{transition:transform .45s ease,fill .45s ease}.trace-chip{color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:1fr}.stage{min-height:420px}#fly-svg{height:325px}.top{flex-direction:column}.status{justify-content:flex-start}}@media(max-width:520px){.app{padding:16px 11px 28px}.panel-head,.timeline-body{padding-left:14px;padding-right:14px}.readouts{padding-left:14px;padding-right:14px}.stage{min-height:365px}.fly-state{right:12px;top:12px}.fly-label{left:14px}.readouts{grid-template-columns:repeat(2,1fr);gap:7px}.readout .v{font-size:16px}}
</style>
</head>
<body>
<main class="app">
<header class="top"><div><div class="eyebrow">Stonkfly / research console</div><h1 class="title">Fly-inspired neural signal replay</h1><p class="sub"><span id="symbol">HDFCBANK</span> · historical NSE paper replay · inspect the model-output trace</p></div><div class="status"><span class="pill live">PAPER ONLY</span><span class="pill" id="period">—</span><span class="pill">No consciousness or agency claim</span></div></header>
<section class="grid">
<div class="panel"><div class="panel-head"><div><div class="panel-title">Motor-output visualization</div><div class="panel-meta">Abstract rendering of decoded motor-output signals</div></div><div class="controls"><button id="prev" type="button" aria-label="Previous observation">‹</button><button id="play" type="button">▶ Play</button><button id="next" type="button" aria-label="Next observation">›</button></div></div><div class="stage"><div id="fly-state" class="fly-state HOLD">Decoded output: HOLD</div><div id="execution-status" class="pill" style="position:absolute;right:20px;top:72px;z-index:2">No trade executed</div><svg id="fly-svg" viewBox="0 0 720 400" role="img" aria-label="Abstract rendered body pose for the decoded model output"><defs><radialGradient id="thorax"><stop stop-color="#d5efb0"/><stop offset="1" stop-color="#5d9270"/></radialGradient><radialGradient id="abdomen"><stop stop-color="#7ab28b"/><stop offset="1" stop-color="#1e4a45"/></radialGradient></defs><g id="fly-body" transform="translate(360 202)"><g id="wings"><ellipse class="wing" cx="-72" cy="-52" rx="92" ry="38" transform="rotate(-24)"/><ellipse class="wing" cx="72" cy="-52" rx="92" ry="38" transform="rotate(24)"/></g><g id="legs"><path class="leg" d="M-32 46 L-100 78 L-135 70"/><path class="leg" d="M-38 58 L-104 123 L-138 132"/><path class="leg" d="M-24 66 L-60 144 L-90 171"/><path class="leg" d="M32 46 L100 78 L135 70"/><path class="leg" d="M38 58 L104 123 L138 132"/><path class="leg" d="M24 66 L60 144 L90 171"/></g><ellipse class="bodypart" fill="url(#abdomen)" cx="0" cy="64" rx="53" ry="98" transform="rotate(90)"/><ellipse class="bodypart" fill="url(#thorax)" cx="0" cy="0" rx="61" ry="56"/><circle class="bodypart" fill="#182d32" cx="0" cy="-62" r="43"/><circle fill="#ff746f" cx="-17" cy="-71" r="10"/><circle fill="#ff746f" cx="17" cy="-71" r="10"/><path d="M-18-94 Q-37-133 -57-138 M18-94 Q37-133 57-138" class="leg"/><circle fill="#a7eb7a" cx="-17" cy="-71" r="3"/><circle fill="#a7eb7a" cx="17" cy="-71" r="3"/></g></svg><div class="fly-label"><span class="trace-chip">Output mapping:</span> BUY raises the rendered posture, SELL turns it, HOLD idles. Pulse color reflects engineered reinforcement/penalty input.</div></div></div>
<div class="panel brain"><div class="panel-head"><div><div class="panel-title">Neural trace</div><div class="panel-meta">Aggregated activity from the full retained connectome; not a biological mind</div></div><span class="pill" id="stimulus">none</span></div><div class="brain-map"><svg viewBox="0 0 420 265" aria-label="Simplified neural activity map"><g id="wires"></g><g id="nodes"><circle class="node input" cx="55" cy="70" r="13"/><circle class="node input" cx="55" cy="132" r="13"/><circle class="node input" cx="55" cy="194" r="13"/><circle class="node kc" cx="145" cy="70" r="14"/><circle class="node kc" cx="145" cy="132" r="14"/><circle class="node kc" cx="145" cy="194" r="14"/><circle class="node decision" cx="255" cy="88" r="16"/><circle class="node decision" cx="255" cy="178" r="16"/><circle class="node gate" cx="340" cy="55" r="12"/><circle class="node dan" cx="340" cy="132" r="12"/><circle class="node dan" cx="340" cy="209" r="12"/></g><g fill="#91a8ac" font-size="10"><text x="30" y="25">visual input</text><text x="124" y="25">KC-layer activity</text><text x="227" y="25">motor readout</text><text x="315" y="25">training signals</text><text x="31" y="91">price</text><text x="31" y="153">shape</text><text x="31" y="215">volume</text><text x="208" y="82">left motor</text><text x="208" y="195">right motor</text><text x="357" y="43">gate</text><text x="357" y="128">reward</text><text x="350" y="227">aversive</text></g></svg></div><div class="brain-caption">Only aggregate rates are visualized; 166,700 neurons are not individually rendered.</div><div class="readouts"><div class="readout"><div class="k">Left motor</div><div class="v" id="left">— Hz</div></div><div class="readout"><div class="k">Right motor</div><div class="v mint" id="right">— Hz</div></div><div class="readout"><div class="k">Difference</div><div class="v" id="diff">— Hz</div></div><div class="readout"><div class="k">Gate spikes</div><div class="v amber" id="gate">—</div></div><div class="readout"><div class="k">KC spikes</div><div class="v" id="kc">—</div></div><div class="readout"><div class="k">Changed edges</div><div class="v purple" id="edges">—</div></div></div></div>
</section>
<section class="panel timeline"><div class="panel-head"><div><div class="panel-title">Replay timeline</div><div class="panel-meta">Scrub the exact market observation and see what the model received</div></div><span class="pill" id="event-count">—</span></div><div class="timeline-body"><canvas class="chart" id="chart" width="1000" height="380" aria-label="Price and equity timeline"></canvas><input id="scrub" class="range" type="range" min="0" max="0" value="0" aria-label="Replay event"><div class="event-line"><span id="event-date">—</span><strong id="event-detail">—</strong><span id="event-index">—</span></div><div class="legend"><span><i class="dot" style="background:var(--cyan)"></i>normalized NSE price</span><span><i class="dot" style="background:var(--mint)"></i>paper equity</span><span><i class="dot" style="background:var(--amber)"></i>reward</span><span><i class="dot" style="background:var(--red)"></i>aversive</span></div><div class="note">This is an interpretive observability UI. The body pose is a visual encoding of the fixed decoder output; it does not indicate consciousness, feelings, intentions, perception, memory, agency, or a biologically valid trading strategy.</div></div></section>
</main>
<script>
const EVENTS = __EVENTS__;
let selected=0, playing=false, timer=null;
const $=id=>document.getElementById(id);
const wirePairs=[[55,70,145,70],[55,132,145,132],[55,194,145,194],[145,70,255,88],[145,132,255,88],[145,132,255,178],[145,194,255,178],[255,88,340,55],[255,88,340,132],[255,178,340,132],[255,178,340,209]];
$('wires').innerHTML=wirePairs.map(([x1,y1,x2,y2])=>`<line class="wire" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`).join('');
const css=getComputedStyle(document.documentElement);
function num(v,d=0){const n=Number(v);return Number.isFinite(n)?n:d}
function fmt(v,d=2){return num(v).toFixed(d)}
function eventDate(e){return new Date(num(e.timestamp)*1000).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
function setPulse(kind){const stage=document.querySelector('.stage');stage.classList.remove('pulse');if(kind!=='none'){stage.style.setProperty('--pulse-color',kind==='reward'?'#a7eb7a':'#ff746f');void stage.offsetWidth;stage.classList.add('pulse')}}
function drawBrain(e){const n=e.neural||{};const left=num(n.left_hz),right=num(n.right_hz),diff=num(n.difference_hz),gate=num(n.gate_spikes),kc=num(n.KC_spikes),edges=num((e.memory||{}).changed_edges);$('left').textContent=fmt(left)+' Hz';$('right').textContent=fmt(right)+' Hz';$('diff').textContent=(diff>=0?'+':'')+fmt(diff)+' Hz';$('gate').textContent=gate;$('kc').textContent=kc;$('edges').textContent=edges;const nodes=[...document.querySelectorAll('#nodes .node')];nodes.forEach((node,i)=>{let amp=i<3?Math.min(1,num(kc)/100):i<6?Math.min(1,num(edges)/3200):i<8?Math.min(1,Math.abs(diff)/5):i===8?Math.min(1,gate/10):i===9?Math.min(1,num(n.reward_spikes)/10):Math.min(1,num(n.aversive_spikes)/10);node.style.opacity=String(.35+.65*amp);node.setAttribute('r',String((i<6?13:12)+amp*7))})}
function drawChart(){const c=$('chart'),ctx=c.getContext('2d'),w=c.width=c.clientWidth*2,h=c.height=c.clientHeight*2;ctx.scale(2,2);const W=c.clientWidth,H=c.clientHeight;ctx.clearRect(0,0,W,H);ctx.fillStyle='#09171b';ctx.fillRect(0,0,W,H);const prices=EVENTS.map(e=>num(e.price)),eq=EVENTS.map(e=>num(e.equity));const minP=Math.min(...prices),maxP=Math.max(...prices),minE=Math.min(...eq),maxE=Math.max(...eq);const x=i=>24+(W-42)*(i/Math.max(1,EVENTS.length-1));const y=(v,lo,hi)=>H-24-(H-42)*((v-lo)/Math.max(.0001,hi-lo));function line(vals,lo,hi,color){ctx.beginPath();vals.forEach((v,i)=>i?ctx.lineTo(x(i),y(v,lo,hi)):ctx.moveTo(x(i),y(v,lo,hi)));ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke()}ctx.strokeStyle='rgba(145,168,172,.15)';ctx.lineWidth=1;for(let i=0;i<5;i++){let yy=20+i*(H-44)/4;ctx.beginPath();ctx.moveTo(20,yy);ctx.lineTo(W-14,yy);ctx.stroke()}line(prices,minP,maxP,'#71e0d2');line(eq,minE,maxE,'#a7eb7a');EVENTS.forEach((e,i)=>{if(e.stimulus!=='none'){ctx.fillStyle=e.stimulus==='reward'?'#f3d476':'#ff746f';ctx.beginPath();ctx.arc(x(i),H-13,3,0,Math.PI*2);ctx.fill()}});ctx.fillStyle='#91a8ac';ctx.font='11px Inter, sans-serif';ctx.fillText('price',24,15);ctx.fillText('equity',W-58,15);ctx.fillText(eventDate(EVENTS[0]),24,H-3);ctx.fillText(eventDate(EVENTS[Math.floor((EVENTS.length-1)/2)]),W/2-38,H-3);ctx.fillText(eventDate(EVENTS[EVENTS.length-1]),W-86,H-3);ctx.strokeStyle='#edf5f1';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x(selected),y(prices[selected],minP,maxP),4,0,Math.PI*2);ctx.stroke()}
function render(){const e=EVENTS[selected],n=e.neural||{};const side=e.side||'HOLD';const fs=$('fly-state');fs.textContent=`Decoded output: ${side}`;fs.className='fly-state '+side;$('execution-status').textContent=e.execution==='FILLED'?'Paper fill recorded':e.execution==='VETO'?'Proposal vetoed':'No trade executed';$('stimulus').textContent=e.stimulus||'none';$('stimulus').style.color=e.stimulus==='reward'?'var(--mint)':e.stimulus==='aversive'?'var(--red)':'var(--muted)';$('event-date').textContent=eventDate(e);$('event-detail').textContent=`${side} · ₹${fmt(num(e.price),2)} · equity ${fmt(num(e.equity),2)}`;$('event-index').textContent=`${selected+1} / ${EVENTS.length}`;const body=$('fly-body'),wings=$('wings');body.style.transform=`translate(360 202) rotate(${side==='BUY'?-5:side==='SELL'?7:0}deg) translateY(${side==='BUY'?-5:side==='SELL'?4:0}px)`;wings.style.opacity=side==='HOLD'?'.72':'1';wings.style.transform=side==='BUY'?'scale(1.08)':side==='SELL'?'scale(.94)':'scale(1)';drawBrain(e);setPulse(e.stimulus||'none');drawChart();$('scrub').value=selected}
function advance(){selected=(selected+1)%EVENTS.length;render()}
$('scrub').max=Math.max(0,EVENTS.length-1);$('event-count').textContent=`${EVENTS.length} observations`;$('period').textContent=EVENTS.length?`${eventDate(EVENTS[0])} → ${eventDate(EVENTS[EVENTS.length-1])}`:'no trace';$('symbol').textContent=__SYMBOL__;$('scrub').addEventListener('input',e=>{selected=Number(e.target.value);render()});$('prev').addEventListener('click',()=>{selected=Math.max(0,selected-1);render()});$('next').addEventListener('click',()=>{selected=Math.min(EVENTS.length-1,selected+1);render()});$('play').addEventListener('click',()=>{playing=!playing;$('play').textContent=playing?'Ⅱ Pause':'▶ Play';if(playing){timer=setInterval(advance,650)}else clearInterval(timer)});window.addEventListener('resize',drawChart);render();
</script>
</body></html>'''


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('--events', type=Path, required=True)
    parser.add_argument('--symbol', default='HDFCBANK')
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    events = [json.loads(line) for line in args.events.read_text().splitlines() if line.strip()]
    html = HTML_TEMPLATE.replace('__EVENTS__', json.dumps(events, ensure_ascii=False).replace('</', '<\\/'))
    html = html.replace('__SYMBOL__', json.dumps(args.symbol))
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(html, encoding='utf-8')
    print(args.out)


if __name__ == '__main__':
    main()
